feed:
{{- /* /picks/atom.xml — preserved for existing subscribers.
      Pulls items from /margins/ with rating >= 4 (the "loved" subset)
      and emits up to 50 most recent. The HTML page at /picks/ is a
      separate, curator-friendly view of the same data. */ -}}
{{- /* Threshold is configurable via [params.margins].loved_threshold in hugo.toml */ -}}
{{- $marginsCfg := .Site.Params.margins | default dict -}}
{{- $threshold := float (index $marginsCfg "loved_threshold" | default 5) -}}
{{- $items := slice -}}
{{- range where .Site.RegularPages "Section" "margins" -}}
  {{- $r := .Params.rating | default 0 -}}
  {{- if ge (float $r) $threshold -}}
    {{- $items = $items | append . -}}
  {{- end -}}
{{- end -}}
{{- $items = first 50 (sort $items "Date" "desc") -}}
{{- $self := .OutputFormats.Get "Atom" -}}
{{- $html := .OutputFormats.Get "HTML" -}}
{{- $owner := .Site.Params.copyright_holder | default .Site.Title -}}
{{ printf (i18n "feedTitlePicks" | default "%s’s Loved") $owner | htmlUnescape | transform.XMLEscape }}
{{ .Permalink }}
{{ with index $items 0 }}{{ .Lastmod.Format "2006-01-02T15:04:05Z07:00" }}{{ else }}{{ now.UTC.Format "2006-01-02T15:04:05Z07:00" }}{{ end }}
{{- with $self }}

{{- end }}
{{- with $html }}

{{- end }}
Movies, music, and books rated {{ $threshold }}★ or higher.
Hugo
{{- range $items }}

  {{ .Title | htmlUnescape | transform.XMLEscape }}

  {{ .Permalink }}
  {{ .Lastmod.Format "2006-01-02T15:04:05Z07:00" }}
  {{- with .Date }}
  {{ .Format "2006-01-02T15:04:05Z07:00" }}
  {{- end }}

    {{ with .Params.author }}{{ . | htmlUnescape | transform.XMLEscape }}{{ else }}{{ $.Site.Title | htmlUnescape | transform.XMLEscape }}{{ end }}

  {{- with .Params.description }}
  {{ . | plainify | htmlUnescape | transform.XMLEscape }}
  {{- else }}{{ with .Summary }}
  {{ . | plainify | htmlUnescape | transform.XMLEscape }}
  {{- end }}{{ end }}
  {{- /* Thumbnail via resource pipeline — Hugo only publishes assets
         that get transformed, so .Resize is what makes the URL valid
         on prod. External URLs pass through. */}}
  {{- $img := .Params.img | default .Params.image }}
  {{- $imgURL := "" }}
  {{- $imgType := "image/jpeg" }}
  {{- if $img }}
    {{- if hasPrefix $img "http" }}
      {{- $imgURL = $img }}
      {{- $ext := path.Ext $imgURL | lower }}
      {{- if eq $ext ".png" }}{{ $imgType = "image/png" }}{{ else if eq $ext ".webp" }}{{ $imgType = "image/webp" }}{{ else if eq $ext ".gif" }}{{ $imgType = "image/gif" }}{{ else if eq $ext ".avif" }}{{ $imgType = "image/avif" }}{{ end }}
    {{- else }}
      {{- $imgRes := resources.Get (strings.TrimPrefix "/" $img) }}
      {{- if $imgRes }}
        {{- $thumb := $imgRes.Resize "800x webp q85" }}
        {{- $imgURL = $thumb.Permalink }}
        {{- $imgType = "image/webp" }}
      {{- else }}
        {{- $imgURL = $img | absURL }}
      {{- end }}
    {{- end }}

  {{- end }}
  {{ if $imgURL }}<p><img src="{{ $imgURL }}" alt="{{ .Title | htmlUnescape | transform.XMLEscape }}" /></p>{{ end }}{{ .Content | safeHTML }}

{{- end }}
